insert into audit_log (
    id, workspace_id, user_id, action, resource_type, resource_id, outcome, payload, created_at
) values (
    #{id}, #{workspaceId}, #{userId}, #{action}, #{resourceType}, #{resourceId},
    #{outcome}, #{payload}, #{createdAt}
)

mapper.select:
select id, workspace_id, user_id, action, resource_type, resource_id, outcome, payload, created_at
from audit_log
where workspace_id = #{workspaceId}

    and action = #{action}


    and resource_type = #{resourceType}


    and user_id = #{userId}


    and created_at >= #{from}


    and created_at <= #{to}

order by created_at desc, id desc
limit #{limit}
